import { Bot } from 'grammy';
import dotenv from 'dotenv';
dotenv.config();
const token = process.env.TELEGRAM_BOT_TOKEN;
if (!token) {
    console.log('TELEGRAM_BOT_TOKEN not set - bot not started');
    process.exit(0);
}
const bot = new Bot(token);
bot.command('start', (ctx) => ctx.reply('FreshCart bot. Use /catalog or visit web shop.'));
bot.command('catalog', (ctx) => ctx.reply('Catalog link: http://localhost:5173/catalog'));
bot.command('orders', (ctx) => ctx.reply('Check orders via web/app (placeholder).'));
bot.start();
console.log('FreshCart bot started');
